// Free root and eight ports on a supplied labeled 26-core. Each port has 6 or 7 core neighbors. No cube contact profile assumed.
use std::io::{self,BufRead};use std::collections::HashMap;type A=[u32;26];const F:u32=(1<<26)-1;
fn alpha(a:&A,m:u32,cache:&mut HashMap<u32,u8>)->u8{if m==0{return 0}if let Some(&v)=cache.get(&m){return v}let i=m.trailing_zeros()as usize;let r=m&(m-1);let v=alpha(a,r,cache).max(1+alpha(a,r&!a[i],cache));cache.insert(m,v);v}
fn push(a:&A,sub:&[(u32,u8)],s:u32,c:&mut HashMap<u32,u8>)->Option<Vec<(u32,u8)>>{let mut v=sub.to_vec();for &(m,k)in sub{let n=m&!s;if n.count_ones()+((k+1)as u32)>8 && alpha(a,n,c)+k+1>8{return None}v.push((n,k+1))}Some(v)}
fn choose(a:&A,p:&mut Vec<u32>,opts:&[u32],sub:&[(u32,u8)],c:&mut HashMap<u32,u8>,deg:[u8;26])->bool{for(i,&s)in opts.iter().enumerate(){let mut d=deg;for j in 0..26{d[j]+=(s>>j&1)as u8}if d.iter().any(|&x|x>8||x+7-(p.len()as u8)<7){continue}if let Some(v)=push(a,sub,s,c){p.push(s);if p.len()==8{return true}let o:Vec<_>=opts[i..].iter().copied().filter(|&t|alpha(a,F&!(s|t),c)<=6).collect();if choose(a,p,&o,&v,c,d){return true}p.pop();}}false}
fn main(){for l in io::stdin().lock().lines(){let a:A=l.unwrap().split_whitespace().map(|s|s.parse().unwrap()).collect::<Vec<_>>().try_into().unwrap();let mut ss=vec![0u32];for i in 0..26{for k in 0..ss.len(){if ss[k]&a[i]==0{ss.push(ss[k]|1<<i)}}}let rows:Vec<_>=ss.into_iter().filter(|s|(6..=7).contains(&s.count_ones())).collect();let mut p=vec![];choose(&a,&mut p,&rows,&[(F,0)],&mut HashMap::new(),a.map(|v|v.count_ones()as u8));println!("{:?}",p)}}
